import { expect, expectStatus, test } from "../../fixtures";

interface VendorOut {
  id: string;
  name: string;
  status: "draft" | "in_review" | "approved" | "rejected";
}

interface VendorPage {
  items: VendorOut[];
  total: number;
  limit: number;
  offset: number;
}

test.describe("vendor list search and status filter", () => {
  test(
    "search and the status filter apply together",
    { tag: "@LIF-14" },
    async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const word = `lif14term${Date.now()}${Math.random().toString(36).slice(2, 8)}`;

      const draftResponse = await member.post("/api/vendors", {
        data: {
          name: `${word} draft vendor`,
          category: "software",
          contact_email: `draft-${word}@example.test`,
        },
      });
      const draftVendor = await expectStatus<VendorOut>(draftResponse, 201);

      const reviewResponse = await member.post("/api/vendors", {
        data: {
          name: `${word} review vendor`,
          category: "services",
          contact_email: `review-${word}@example.test`,
        },
      });
      const reviewVendor = await expectStatus<VendorOut>(reviewResponse, 201);

      const submitResponse = await member.post(`/api/vendors/${reviewVendor.id}/submit`);
      const submitted = await expectStatus<VendorOut>(submitResponse, 200);
      expect(submitted.status).toBe("in_review");

      // Act
      const listResponse = await member.get("/api/vendors", {
        params: { q: word, status: "in_review" },
      });

      // Assert
      const page = await expectStatus<VendorPage>(listResponse, 200);
      expect(page.items.map((v) => v.id)).toEqual([reviewVendor.id]);
      expect(page.items.map((v) => v.id)).not.toContain(draftVendor.id);
      expect(page.items[0].status).toBe("in_review");
      expect(page.total).toBe(1);
    },
  );
});
